// Noise_XX_25519_ChaChaPoly_SHA256 (protocol/PROTOCOL.md §3), the app side (initiator).
// Mirrors firmware/app/src/noise.c byte for byte; protocol/noise_vectors.json (generated by
// the firmware) is the shared test.
//
//   msg1  app -> device  e                 32 bytes
//   msg2  device -> app  e, ee, s, es      96 bytes
//   msg3  app -> device  s, se             64 bytes
//
// Transport: ChaChaPoly, nonce = 4 zero bytes || u64 little-endian counter, no associated
// data, 16-byte tag appended. Messages may exceed Noise's 65535-byte limit (framing caps them).
import { chacha20poly1305 } from '@noble/ciphers/chacha.js';
import { x25519 } from '@noble/curves/ed25519.js';
import { hmac } from '@noble/hashes/hmac.js';
import { sha256 } from '@noble/hashes/sha2.js';
import { concatBytes, utf8ToBytes } from '@noble/hashes/utils.js';

const PROTOCOL_NAME = utf8ToBytes('Noise_XX_25519_ChaChaPoly_SHA256'); // 32 bytes: used as h directly
const PROLOGUE = utf8ToBytes('tredder/1');
export const TAG = 16;
export const MSG2_LEN = 96;

function nonce(n: bigint): Uint8Array {
  const iv = new Uint8Array(12);
  new DataView(iv.buffer).setBigUint64(4, n, true);
  return iv;
}

function hkdf2(ck: Uint8Array, ikm: Uint8Array): [Uint8Array, Uint8Array] {
  const prk = hmac(sha256, ck, ikm);
  const o1 = hmac(sha256, prk, Uint8Array.of(1));
  const o2 = hmac(sha256, prk, concatBytes(o1, Uint8Array.of(2)));
  prk.fill(0);
  return [o1, o2];
}

export class CipherState {
  private n = 0n;
  constructor(private readonly k: Uint8Array) {}
  seal(plain: Uint8Array): Uint8Array {
    return chacha20poly1305(this.k, nonce(this.n++)).encrypt(plain);
  }
  /** Throws on a bad tag; the counter only advances on success. */
  open(sealed: Uint8Array): Uint8Array {
    const p = chacha20poly1305(this.k, nonce(this.n)).decrypt(sealed);
    this.n++;
    return p;
  }
}

export interface Session {
  send: CipherState;
  recv: CipherState;
  /** Handshake hash: binds the pairing code to this exact session. */
  hash: Uint8Array;
  /** The device's static public key (pinned by the app after pairing). */
  remoteStatic: Uint8Array;
}

/** XX initiator. Use: msg1(), then readMsg2(), then msg3(), then split(). */
export class XXInitiator {
  private ck: Uint8Array;
  private h: Uint8Array;
  private k: Uint8Array | null = null;
  private n = 0n;
  private readonly sPub: Uint8Array;
  private readonly ePub: Uint8Array;
  private re: Uint8Array | null = null;
  private rs: Uint8Array | null = null;
  private step = 0;

  constructor(
    private readonly s: Uint8Array,
    private readonly e: Uint8Array = x25519.utils.randomSecretKey(),
  ) {
    this.h = PROTOCOL_NAME.slice();
    this.ck = this.h.slice();
    this.mixHash(PROLOGUE);
    this.sPub = x25519.getPublicKey(s);
    this.ePub = x25519.getPublicKey(e);
  }

  private mixHash(d: Uint8Array) {
    this.h = sha256(concatBytes(this.h, d));
  }
  private mixKey(ikm: Uint8Array) {
    [this.ck, this.k] = hkdf2(this.ck, ikm);
    this.n = 0n;
  }
  private mixDh(priv: Uint8Array, pub: Uint8Array) {
    const shared = x25519.getSharedSecret(priv, pub);
    this.mixKey(shared);
    shared.fill(0);
  }
  private encryptAndHash(p: Uint8Array): Uint8Array {
    const c = this.k ? chacha20poly1305(this.k, nonce(this.n++), this.h).encrypt(p) : p;
    this.mixHash(c);
    return c;
  }
  private decryptAndHash(c: Uint8Array): Uint8Array {
    if (!this.k) {
      this.mixHash(c);
      return c;
    }
    const p = chacha20poly1305(this.k, nonce(this.n), this.h).decrypt(c);
    this.n++;
    this.mixHash(c);
    return p;
  }

  msg1(): Uint8Array {
    if (this.step !== 0) throw new Error('noise: msg1 out of order');
    this.step = 1;
    this.mixHash(this.ePub);
    return concatBytes(this.ePub, this.encryptAndHash(new Uint8Array(0)));
  }

  readMsg2(m: Uint8Array) {
    if (this.step !== 1 || m.length !== MSG2_LEN) throw new Error('noise: bad msg2');
    this.step = -1; // poisoned unless everything below succeeds
    this.re = m.slice(0, 32);
    this.mixHash(this.re);
    this.mixDh(this.e, this.re); // ee
    this.rs = this.decryptAndHash(m.slice(32, 80)); // s
    this.mixDh(this.e, this.rs); // es
    this.decryptAndHash(m.slice(80)); // empty payload
    this.step = 2;
  }

  msg3(): Uint8Array {
    if (this.step !== 2 || !this.re) throw new Error('noise: msg3 out of order');
    const c = this.encryptAndHash(this.sPub); // s
    this.mixDh(this.s, this.re); // se
    this.step = 3;
    return concatBytes(c, this.encryptAndHash(new Uint8Array(0)));
  }

  split(): Session {
    if (this.step !== 3 || !this.rs) throw new Error('noise: handshake not finished');
    const [k1, k2] = hkdf2(this.ck, new Uint8Array(0));
    this.step = -1;
    this.e.fill(0);
    return { send: new CipherState(k1), recv: new CipherState(k2), hash: this.h, remoteStatic: this.rs };
  }
}

/** The 6-digit code both screens show: SHA-256("tredder pairing code" || h)[0..4] BE mod 1e6. */
export function pairCode(hash: Uint8Array): string {
  const d = sha256(concatBytes(utf8ToBytes('tredder pairing code'), hash));
  const v = new DataView(d.buffer, d.byteOffset).getUint32(0) % 1_000_000;
  return v.toString().padStart(6, '0');
}

export const newStaticKey = (): Uint8Array => x25519.utils.randomSecretKey();
export const publicKeyOf = (priv: Uint8Array): Uint8Array => x25519.getPublicKey(priv);
